    "terms.title": "Terms & Conditions",
    "terms.lastupdated": "Last updated:",
    "terms.section1.title": "1. Acceptance of Terms",
    "terms.section1.content": "By accessing and using WhatTheFood, you accept and agree to be bound by the terms and provision of this agreement.",
    "terms.section2.title": "2. Use License",
    "terms.section2.content": "Permission is granted to temporarily use WhatTheFood for personal, non-commercial use only. This is the grant of a license, not a transfer of title.",
    "terms.section3.title": "3. Disclaimer",
    "terms.section3.content": "The nutritional information provided is for informational purposes only and should not be considered medical advice. Always consult with a healthcare professional for dietary guidance.",
    "terms.section4.title": "4. Account Terms",
    "terms.section4.content": "You are responsible for maintaining the security of your account and password. WhatTheFood cannot and will not be liable for any loss or damage from your failure to comply with this security obligation.",
    "terms.section5.title": "5. Subscription Terms",
    "terms.section5.content": "Premium subscriptions are billed monthly or annually. You may cancel your subscription at any time, and cancellation will take effect at the end of your current billing period.",
    "terms.section6.title": "6. Modifications",
    "terms.section6.content": "WhatTheFood reserves the right to modify or replace these Terms at any time. Continued use of the service after any changes constitutes acceptance of the new Terms.",
    
    // Privacy Page Section
    "privacy.title": "Privacy Policy",
    "privacy.lastupdated": "Last updated:",
    "privacy.section1.title": "1. Information We Collect",
    "privacy.section1.content": "We collect information you provide directly to us, such as when you create an account, upload food images, or communicate with us. This includes your email address, uploaded images, and scan history.",
    "privacy.section2.title": "2. How We Use Your Information",
    "privacy.section2.content": "We use the information we collect to provide, maintain, and improve our services, including analyzing food images and generating nutritional reports. We do not sell your personal information to third parties.",
    "privacy.section3.title": "3. Data Security",
    "privacy.section3.content": "We implement appropriate technical and organizational measures to protect your personal information against unauthorized access, alteration, disclosure, or destruction.",
    "privacy.section4.title": "4. Your Rights",
    "privacy.section4.content": "You have the right to access, correct, or delete your personal information. You can manage your data through your account settings or by contacting us directly.",
    "privacy.section5.title": "5. Cookies",
    "privacy.section5.content": "We use cookies and similar technologies to enhance your experience, analyze usage, and assist in our marketing efforts.",
    "privacy.section6.title": "6. Contact Us",
    "privacy.section6.content": "If you have questions about this Privacy Policy, please contact us at privacy@whatthefood.io",
    
