    // FAQ Section
    "faq.title": "Preguntas Frecuentes",
    "faq.subtitle": "Todo lo que necesitas saber sobre WhatTheFood",
    "faq.accuracy.question": "¿Qué tan precisa es el análisis de alimentos con IA?",
    "faq.accuracy.answer": "Nuestra IA está entrenada con millones de imágenes de alimentos y datos nutricionales. Aunque nos esforzamos por una alta precisión, los resultados son estimaciones basadas en análisis visual. Los usuarios Premium pueden ajustar los tamaños de porción y los ingredientes para obtener resultados aún más precisos.",
    "faq.types.question": "¿Qué tipos de alimentos puedo escanear?",
    "faq.types.answer": "¡Puedes escanear cualquier tipo de comida de cualquier cocina! Nuestra IA reconoce miles de platos, desde comidas caseras hasta platos de restaurante y alimentos envasados.",
    "faq.freescans.question": "¿Cuántos escaneos obtengo gratis?",
    "faq.freescans.answer": "Los usuarios gratuitos obtienen 5 escaneos en total para probar el servicio. Después de eso, puedes crear una cuenta gratuita para 3 escaneos por día, o actualizar a Premium para escaneos ilimitados.",
    "faq.export.question": "¿Puedo exportar mis datos nutricionales?",
    "faq.export.answer": "¡Sí! Los miembros Premium pueden exportar su historial de escaneos y datos nutricionales como informes PDF, perfectos para compartir con proveedores de atención médica o seguimiento personal.",
    "faq.premium.question": "¿Qué incluye el plan Premium?",
    "faq.premium.answer": "Premium incluye escaneos ilimitados, historial completo de escaneos, herramientas de ajuste de porciones, widget personalizable para tu sitio web, informes PDF y una experiencia sin anuncios con soporte prioritario.",
    "faq.refund.question": "¿Cómo funciona la política de reembolso?",
    "faq.refund.answer": "Ofrecemos una garantía de devolución de dinero de 30 días. Si no estás satisfecho con tu suscripción Premium, contáctanos dentro de 30 días para un reembolso completo.",
    "faq.dietary.question": "¿Puedo usar esto para restricciones dietéticas?",
    "faq.dietary.answer": "¡Absolutamente! Nuestro desglose nutricional detallado te ayuda a rastrear nutrientes específicos relevantes para tus necesidades dietéticas, ya sea que estés manejando alergias, siguiendo dietas específicas o monitoreando macros.",
    "faq.security.question": "¿Mis datos están seguros?",
    "faq.security.answer": "Sí, nos tomamos la privacidad en serio. Tus escaneos de alimentos y datos están encriptados y nunca se comparten con terceros. Lee nuestra Política de Privacidad completa para más detalles.",
    
