    // FAQ Section
    "faq.title": "Questions fréquemment posées",
    "faq.subtitle": "Tout ce que vous devez savoir sur WhatTheFood",
    "faq.accuracy.question": "Quelle est la précision de l'analyse alimentaire par IA ?",
    "faq.accuracy.answer": "Notre IA est formée sur des millions d'images alimentaires et de données nutritionnelles. Bien que nous visions une grande précision, les résultats sont des estimations basées sur l'analyse visuelle. Les utilisateurs Premium peuvent ajuster les tailles de portion et les ingrédients pour des résultats encore plus précis.",
    "faq.types.question": "Quels types d'aliments puis-je scanner ?",
    "faq.types.answer": "Vous pouvez scanner n'importe quel type d'aliment de n'importe quelle cuisine ! Notre IA reconnaît des milliers de plats, des repas faits maison aux plats de restaurant et aux aliments emballés.",
    "faq.freescans.question": "Combien de scans obtenez-je gratuitement ?",
    "faq.freescans.answer": "Les utilisateurs gratuits obtiennent 5 scans au total pour essayer le service. Après cela, vous pouvez créer un compte gratuit pour 3 scans par jour, ou passer à Premium pour des scans illimités.",
    "faq.export.question": "Puis-je exporter mes données nutritionnelles ?",
    "faq.export.answer": "Oui ! Les membres Premium peuvent exporter leur historique de scans et leurs données nutritionnelles sous forme de rapports PDF, parfaits pour partager avec des prestataires de soins de santé ou un suivi personnel.",
    "faq.premium.question": "Qu'est-ce qui est inclus dans le plan Premium ?",
    "faq.premium.answer": "Premium comprend des scans illimités, un historique complet des scans, des outils d'ajustement des portions, un widget personnalisable pour votre site web, des rapports PDF et une expérience sans publicité avec support prioritaire.",
    "faq.refund.question": "Comment fonctionne la politique de remboursement ?",
    "faq.refund.answer": "Nous offrons une garantie de remboursement de 30 jours. Si vous n'êtes pas satisfait de votre abonnement Premium, contactez-nous dans les 30 jours pour un remboursement complet.",
    "faq.dietary.question": "Puis-je utiliser cela pour les restrictions alimentaires ?",
    "faq.dietary.answer": "Absolument ! Notre détail nutritionnel détaillé vous aide à suivre les nutriments spécifiques pertinents pour vos besoins alimentaires, que vous gériez des allergies, suiviez des régimes spécifiques ou surveilliez les macros.",
    "faq.security.question": "Mes données sont-elles sécurisées ?",
    "faq.security.answer": "Oui, nous prenons la confidentialité au sérieux. Vos scans alimentaires et vos données sont cryptés et jamais partagés avec des tiers. Lisez notre politique de confidentialité complète pour plus de détails.",
    
