    // FAQ Section
    "faq.title": "Häufig gestellte Fragen",
    "faq.subtitle": "Alles, was Sie über WhatTheFood wissen müssen",
    "faq.accuracy.question": "Wie genau ist die KI-Lebensmittelanalyse?",
    "faq.accuracy.answer": "Unsere KI wurde mit Millionen von Lebensmittelbildern und Nährwertdaten trainiert. Während wir eine hohe Genauigkeit anstreben, sind die Ergebnisse Schätzungen basierend auf visueller Analyse. Premium-Benutzer können Portionsgrößen und Zutaten anpassen, um noch präzisere Ergebnisse zu erhalten.",
    "faq.types.question": "Welche Arten von Lebensmitteln kann ich scannen?",
    "faq.types.answer": "Sie können jede Art von Lebensmitteln aus jeder Küche scannen! Unsere KI erkennt Tausende von Gerichten, von hausgemachten Mahlzeiten bis hin zu Restaurantgerichten und verpackten Lebensmitteln.",
    "faq.freescans.question": "Wie viele Scans erhalte ich kostenlos?",
    "faq.freescans.answer": "Kostenlose Benutzer erhalten insgesamt 5 Scans, um den Service zu testen. Danach können Sie ein kostenloses Konto für 3 Scans pro Tag erstellen oder auf Premium upgraden für unbegrenzte Scans.",
    "faq.export.question": "Kann ich meine Nährwertdaten exportieren?",
    "faq.export.answer": "Ja! Premium-Mitglieder können ihren Scan-Verlauf und Nährwertdaten als PDF-Berichte exportieren, perfekt zum Teilen mit Gesundheitsdienstleistern oder zur persönlichen Verfolgung.",
    "faq.premium.question": "Was ist im Premium-Plan enthalten?",
    "faq.premium.answer": "Premium umfasst unbegrenzte Scans, vollständigen Scan-Verlauf, Portionsanpassungstools, anpassbares Widget für Ihre Website, PDF-Berichte und eine werbefreie Erfahrung mit Prioritäts-Support.",
    "faq.refund.question": "Wie funktioniert die Rückerstattungsrichtlinie?",
    "faq.refund.answer": "Wir bieten eine 30-tägige Geld-zurück-Garantie. Wenn Sie mit Ihrem Premium-Abonnement nicht zufrieden sind, kontaktieren Sie uns innerhalb von 30 Tagen für eine vollständige Rückerstattung.",
    "faq.dietary.question": "Kann ich dies für diätetische Einschränkungen verwenden?",
    "faq.dietary.answer": "Absolut! Unsere detaillierte Nährwertaufschlüsselung hilft Ihnen, spezifische Nährstoffe zu verfolgen, die für Ihre diätetischen Bedürfnisse relevant sind, unabhängig davon, ob Sie Allergien verwalten, bestimmte Diäten befolgen oder Makros überwachen.",
    "faq.security.question": "Sind meine Daten sicher?",
    "faq.security.answer": "Ja, wir nehmen den Datenschutz ernst. Ihre Lebensmittel-Scans und Daten sind verschlüsselt und werden niemals an Dritte weitergegeben. Lesen Sie unsere vollständige Datenschutzrichtlinie für Details.",
    
