    // FAQ Section
    "faq.title": "Domande frequenti",
    "faq.subtitle": "Tutto ciò che devi sapere su WhatTheFood",
    "faq.accuracy.question": "Quanto è accurata l'analisi alimentare dell'IA?",
    "faq.accuracy.answer": "La nostra IA è addestrata su milioni di immagini alimentari e dati nutrizionali. Mentre ci sforziamo per un'alta accuratezza, i risultati sono stime basate sull'analisi visiva. Gli utenti Premium possono regolare le dimensioni delle porzioni e gli ingredienti per risultati ancora più precisi.",
    "faq.types.question": "Che tipi di cibo posso scansionare?",
    "faq.types.answer": "Puoi scansionare qualsiasi tipo di cibo di qualsiasi cucina! La nostra IA riconosce migliaia di piatti, dai pasti fatti in casa ai piatti del ristorante e agli alimenti confezionati.",
    "faq.freescans.question": "Quante scansioni ottengo gratuitamente?",
    "faq.freescans.answer": "Gli utenti gratuiti ottengono 5 scansioni totali per provare il servizio. Dopo di ciò, puoi creare un account gratuito per 3 scansioni al giorno o passare a Premium per scansioni illimitate.",
    "faq.export.question": "Posso esportare i miei dati nutrizionali?",
    "faq.export.answer": "Sì! I membri Premium possono esportare la loro cronologia di scansioni e dati nutrizionali come report PDF, perfetti per condividere con fornitori di assistenza sanitaria o per il monitoraggio personale.",
    "faq.premium.question": "Cosa è incluso nel piano Premium?",
    "faq.premium.answer": "Premium include scansioni illimitate, cronologia completa delle scansioni, strumenti di regolazione delle porzioni, widget personalizzabile per il tuo sito web, report PDF e un'esperienza senza pubblicità con supporto prioritario.",
    "faq.refund.question": "Come funziona la politica di rimborso?",
    "faq.refund.answer": "Offriamo una garanzia di rimborso di 30 giorni. Se non sei soddisfatto del tuo abbonamento Premium, contattaci entro 30 giorni per un rimborso completo.",
    "faq.dietary.question": "Posso usare questo per restrizioni dietetiche?",
    "faq.dietary.answer": "Assolutamente! Il nostro dettaglio nutrizionale dettagliato ti aiuta a tracciare nutrienti specifici rilevanti per le tue esigenze dietetiche, che tu stia gestendo allergie, seguendo diete specifiche o monitorando i macro.",
    "faq.security.question": "I miei dati sono sicuri?",
    "faq.security.answer": "Sì, prendiamo sul serio la privacy. Le tue scansioni alimentari e i dati sono crittografati e mai condivisi con terze parti. Leggi la nostra politica sulla privacy completa per i dettagli.",
    
