    // Terms Page Section
    "terms.title": "Termini e Condizioni",
    "terms.lastupdated": "Ultimo aggiornamento:",
    "terms.section1.title": "1. Accettazione dei Termini",
    "terms.section1.content": "Accedendo e utilizzando WhatTheFood, accetti e accetti di essere vincolato dai termini e dalle disposizioni di questo accordo.",
    "terms.section2.title": "2. Licenza d'Uso",
    "terms.section2.content": "È concessa l'autorizzazione per utilizzare temporaneamente WhatTheFood solo per uso personale e non commerciale. Questa è la concessione di una licenza, non un trasferimento di titolo.",
    "terms.section3.title": "3. Disclaimer",
    "terms.section3.content": "Le informazioni nutrizionali fornite sono solo a scopo informativo e non devono essere considerate consigli medici. Consultare sempre un professionista sanitario per la guida dietetica.",
    "terms.section4.title": "4. Termini dell'Account",
    "terms.section4.content": "Sei responsabile del mantenimento della sicurezza del tuo account e password. WhatTheFood non può e non sarà responsabile per eventuali perdite o danni derivanti dal mancato rispetto di questo obbligo di sicurezza.",
    "terms.section5.title": "5. Termini di Abbonamento",
    "terms.section5.content": "Gli abbonamenti Premium vengono fatturati mensilmente o annualmente. Puoi cancellare il tuo abbonamento in qualsiasi momento e la cancellazione avrà effetto alla fine del tuo periodo di fatturazione corrente.",
    "terms.section6.title": "6. Modifiche",
    "terms.section6.content": "WhatTheFood si riserva il diritto di modificare o sostituire questi Termini in qualsiasi momento. L'uso continuato del servizio dopo eventuali modifiche costituisce l'accettazione dei nuovi Termini.",
    
    // Privacy Page Section
    "privacy.title": "Politica sulla Privacy",
    "privacy.lastupdated": "Ultimo aggiornamento:",
    "privacy.section1.title": "1. Informazioni che Raccogliamo",
    "privacy.section1.content": "Raccogliamo informazioni che ci fornisci direttamente, come quando crei un account, carichi immagini di cibo o comunichi con noi. Questo include il tuo indirizzo email, le immagini caricate e la cronologia delle scansioni.",
    "privacy.section2.title": "2. Come Utilizziamo le Tue Informazioni",
    "privacy.section2.content": "Utilizziamo le informazioni che raccogliamo per fornire, mantenere e migliorare i nostri servizi, inclusa l'analisi di immagini di cibo e la generazione di rapporti nutrizionali. Non vendiamo le tue informazioni personali a terze parti.",
    "privacy.section3.title": "3. Sicurezza dei Dati",
    "privacy.section3.content": "Implementiamo misure tecniche e organizzative appropriate per proteggere le tue informazioni personali da accesso non autorizzato, alterazione, divulgazione o distruzione.",
    "privacy.section4.title": "4. I Tuoi Diritti",
    "privacy.section4.content": "Hai il diritto di accedere, correggere o eliminare le tue informazioni personali. Puoi gestire i tuoi dati tramite le impostazioni del tuo account o contattandoci direttamente.",
    "privacy.section5.title": "5. Cookie",
    "privacy.section5.content": "Utilizziamo cookie e tecnologie simili per migliorare la tua esperienza, analizzare l'utilizzo e supportare i nostri sforzi di marketing.",
    "privacy.section6.title": "6. Contattaci",
    "privacy.section6.content": "Se hai domande su questa Politica sulla Privacy, contattaci a privacy@whatthefood.io",
    
