    "faq.subtitle": "Tudo que você precisa saber sobre WhatTheFood",
    "faq.accuracy.question": "Quão precisa é a análise de alimentos por IA?",
    "faq.accuracy.answer": "Nossa IA é treinada em milhões de imagens de alimentos e dados nutricionais. Embora busquemos alta precisão, os resultados são estimativas baseadas em análise visual. Usuários Premium podem ajustar tamanhos de porção e ingredientes para resultados ainda mais precisos.",
    "faq.types.question": "Que tipos de alimentos posso escanear?",
    "faq.types.answer": "Você pode escanear qualquer tipo de alimento de qualquer culinária! Nossa IA reconhece milhares de pratos, de refeições caseiras a pratos de restaurante e alimentos embalados.",
