    "faq.freescans.answer": "Usuários gratuitos recebem 5 escaneamentos no total para experimentar o serviço. Depois disso, você pode criar uma conta gratuita para 3 escaneamentos por dia ou atualizar para Premium para escaneamentos ilimitados.",
    "faq.export.question": "Posso exportar meus dados nutricionais?",
    "faq.export.answer": "Sim! Membros Premium podem exportar seu histórico de escaneamentos e dados nutricionais como relatórios PDF, perfeitos para compartilhar com provedores de saúde ou rastreamento pessoal.",
