    "faq.premium.answer": "Premium inclui escaneamentos ilimitados, histórico completo de escaneamentos, ferramentas de ajuste de porção, widget personalizável para seu site, relatórios PDF e uma experiência sem anúncios com suporte prioritário.",
    "faq.refund.question": "Como funciona a política de reembolso?",
    "faq.refund.answer": "Oferecemos uma garantia de reembolso de 30 dias. Se você não estiver satisfeito com sua assinatura Premium, entre em contato conosco dentro de 30 dias para um reembolso completo.",
