    "faq.security.question": "Meus dados estão seguros?",
    "faq.security.answer": "Sim, levamos a privacidade a sério. Seus escaneamentos de alimentos e dados são criptografados e nunca compartilhados com terceiros. Leia nossa política de privacidade completa para detalhes.",
    
