    // FAQ Section
    "faq.title": "よくある質問",
    "faq.subtitle": "WhatTheFoodについて知っておくべきすべて",
    "faq.accuracy.question": "AI食品分析の精度はどのくらいですか？",
    "faq.accuracy.answer": "私たちのAIは、数百万の食品画像と栄養データで訓練されています。高い精度を目指していますが、結果は視覚分析に基づく推定値です。プレミアムユーザーは、ポーションサイズと材料を調整して、さらに正確な結果を得ることができます。",
    "faq.types.question": "どのような種類の食品をスキャンできますか？",
    "faq.types.answer": "あらゆる料理のあらゆる種類の食品をスキャンできます！私たちのAIは、家庭料理からレストランの料理、包装食品まで、数千の料理を認識します。",
    "faq.freescans.question": "無料で何回スキャンできますか？",
    "faq.freescans.answer": "無料ユーザーは、サービスを試すために合計5回のスキャンを取得します。その後、1日3回のスキャンで無料アカウントを作成するか、無制限のスキャンでプレミアムにアップグレードできます。",
    "faq.export.question": "栄養データをエクスポートできますか？",
    "faq.export.answer": "はい！プレミアムメンバーは、スキャン履歴と栄養データをPDFレポートとしてエクスポートでき、医療提供者との共有や個人の追跡に最適です。",
    "faq.premium.question": "プレミアムプランには何が含まれていますか？",
    "faq.premium.answer": "プレミアムには、無制限のスキャン、完全なスキャン履歴、サービング調整ツール、ウェブサイト用のカスタマイズ可能なウィジェット、PDFレポート、広告なしの体験と優先サポートが含まれます。",
    "faq.refund.question": "返金ポリシーはどのように機能しますか？",
    "faq.refund.answer": "30日間の返金保証を提供しています。プレミアムサブスクリプションに満足できない場合は、30日以内にご連絡いただければ全額返金いたします。",
    "faq.dietary.question": "食事制限に使用できますか？",
    "faq.dietary.answer": "もちろんです！詳細な栄養分解により、アレルギーの管理、特定の食事の遵守、マクロの監視など、食事ニーズに関連する特定の栄養素を追跡できます。",
    "faq.security.question": "私のデータは安全ですか？",
    "faq.security.answer": "はい、プライバシーを真剣に受け止めています。食品スキャンとデータは暗号化され、第三者と共有されることはありません。詳細については、完全なプライバシーポリシーをお読みください。",
    
