    // Terms Page Section
    "terms.title": "利用規約",
    "terms.lastupdated": "最終更新：",
    "terms.section1.title": "1. 規約の承認",
    "terms.section1.content": "WhatTheFoodにアクセスして使用することで、本契約の条項と規定に拘束されることに同意したものとみなされます。",
    "terms.section2.title": "2. 使用ライセンス",
    "terms.section2.content": "WhatTheFoodを個人的、非商業的な使用のみに一時的に使用する許可が付与されます。これはライセンスの付与であり、所有権の譲渡ではありません。",
    "terms.section3.title": "3. 免責事項",
    "terms.section3.content": "提供される栄養情報は情報提供のみを目的としており、医療アドバイスと見なされるべきではありません。食事指導については、常に医療専門家に相談してください。",
    "terms.section4.title": "4. アカウント規約",
    "terms.section4.content": "アカウントとパスワードのセキュリティを維持する責任があります。WhatTheFoodは、このセキュリティ義務の不遵守による損失や損害について責任を負いません。",
    "terms.section5.title": "5. サブスクリプション規約",
    "terms.section5.content": "プレミアムサブスクリプションは月額または年額で請求されます。いつでもサブスクリプションをキャンセルでき、キャンセルは現在の請求期間の終了時に有効になります。",
    "terms.section6.title": "6. 変更",
    "terms.section6.content": "WhatTheFoodは、これらの規約をいつでも変更または置き換える権利を留保します。変更後のサービスの継続使用は、新しい規約の承認を構成します。",
    
    // Privacy Page Section
    "privacy.title": "プライバシーポリシー",
    "privacy.lastupdated": "最終更新：",
    "privacy.section1.title": "1. 収集する情報",
    "privacy.section1.content": "アカウント作成、食品画像のアップロード、または当社との通信時など、直接提供していただく情報を収集します。これには、メールアドレス、アップロードされた画像、スキャン履歴が含まれます。",
    "privacy.section2.title": "2. 情報の使用方法",
    "privacy.section2.content": "収集した情報を使用して、食品画像の分析や栄養レポートの生成を含む、サービスの提供、維持、改善を行います。個人情報を第三者に販売することはありません。",
    "privacy.section3.title": "3. データセキュリティ",
    "privacy.section3.content": "個人情報を不正アクセス、改ざん、開示、または破壊から保護するため、適切な技術的および組織的措置を実施しています。",
    "privacy.section4.title": "4. あなたの権利",
    "privacy.section4.content": "個人情報にアクセス、修正、または削除する権利があります。アカウント設定を通じて、または直接お問い合わせいただくことで、データを管理できます。",
    "privacy.section5.title": "5. Cookie",
    "privacy.section5.content": "Cookieや類似のテクノロジーを使用して、体験を向上させ、使用状況を分析し、マーケティング活動を支援します。",
    "privacy.section6.title": "6. お問い合わせ",
    "privacy.section6.content": "このプライバシーポリシーに関するご質問は、privacy@whatthefood.ioまでお問い合わせください",
    
