    "terms.lastupdated": "آخر تحديث:",
    "terms.section1.title": "1. قبول الشروط",
    "terms.section1.content": "من خلال الوصول إلى WhatTheFood واستخدامه، فإنك تقبل وتوافق على الالتزام بشروط وأحكام هذه الاتفاقية.",
    "terms.section2.title": "2. ترخيص الاستخدام",
    "terms.section2.content": "يتم منح الإذن لاستخدام WhatTheFood مؤقتًا للاستخدام الشخصي وغير التجاري فقط. هذا هو منح ترخيص، وليس نقل ملكية.",
    "terms.section3.title": "3. إخلاء المسؤولية",
    "terms.section3.content": "المعلومات الغذائية المقدمة هي لأغراض إعلامية فقط ولا ينبغي اعتبارها نصيحة طبية. استشر دائماً أخصائي رعاية صحية للحصول على إرشادات غذائية.",
    "terms.section4.title": "4. شروط الحساب",
    "terms.section4.content": "أنت مسؤول عن الحفاظ على أمان حسابك وكلمة المرور. لا يمكن لـ WhatTheFood ولن يكون مسؤولاً عن أي خسارة أو ضرر ناتج عن فشلك في الامتثال لهذا الالتزام الأمني.",
    "terms.section5.title": "5. شروط الاشتراك",
    "terms.section5.content": "يتم فوترة الاشتراكات المميزة شهرياً أو سنوياً. يمكنك إلغاء اشتراكك في أي وقت، وسيبدأ الإلغاء في نهاية فترة الفوترة الحالية.",
    "terms.section6.title": "6. التعديلات",
    "terms.section6.content": "تحتفظ WhatTheFood بالحق في تعديل أو استبدال هذه الشروط في أي وقت. الاستمرار في استخدام الخدمة بعد أي تغييرات يشكل قبول الشروط الجديدة.",
    
    // Privacy Page Section
    "privacy.title": "سياسة الخصوصية",
    "privacy.lastupdated": "آخر تحديث:",
    "privacy.section1.title": "1. المعلومات التي نجمعها",
    "privacy.section1.content": "نجمع المعلومات التي تقدمها لنا مباشرة، مثل عندما تنشئ حساباً أو ترفع صور طعام أو تتواصل معنا. يتضمن ذلك عنوان بريدك الإلكتروني والصور المرفوعة وسجل المسح.",
    "privacy.section2.title": "2. كيفية استخدام معلوماتك",
    "privacy.section2.content": "نستخدم المعلومات التي نجمعها لتوفير وصيانة وتحسين خدماتنا، بما في ذلك تحليل صور الطعام وإنشاء تقارير غذائية. لا نبيع معلوماتك الشخصية لأطراف ثالثة.",
    "privacy.section3.title": "3. أمان البيانات",
    "privacy.section3.content": "ننفذ تدابير تقنية وتنظيمية مناسبة لحماية معلوماتك الشخصية من الوصول غير المصرح به أو التعديل أو الكشف أو التدمير.",
    "privacy.section4.title": "4. حقوقك",
    "privacy.section4.content": "لديك الحق في الوصول إلى معلوماتك الشخصية أو تصحيحها أو حذفها. يمكنك إدارة بياناتك من خلال إعدادات حسابك أو بالاتصال بنا مباشرة.",
    "privacy.section5.title": "5. ملفات تعريف الارتباط",
    "privacy.section5.content": "نستخدم ملفات تعريف الارتباط وتقنيات مماثلة لتحسين تجربتك وتحليل الاستخدام ومساعدة جهودنا التسويقية.",
    "privacy.section6.title": "6. اتصل بنا",
    "privacy.section6.content": "إذا كان لديك أسئلة حول سياسة الخصوصية هذه، يرجى الاتصال بنا على privacy@whatthefood.io",
    
